    switch( step ) {

        case 0:
            lcd_show_f(  3 , glyph_dash );
            break;

        case 1:
            lcd_show_f(  3 , glyph_SPACE );
            lcd_show_f(  2 , glyph_dash );
            break;

        case 2:
            lcd_show_f(  2 , glyph_SPACE );
            lcd_show_f(  1 , glyph_dash );
            break;

        case 3:
            lcd_show_f(  1 , glyph_SPACE );
            lcd_show_f(  0 , glyph_dash );
            break;

        case 4:
            lcd_show_f(  0 , glyph_SPACE );
            break;

        default:
            __never_executed();

    }

}


