/*
 * persistent.h
 *
 * This is the structure for the data that we store in the "InfoA" section of flash memory. This data persists through power cycles.
 * We break it out into a header file solely so that the ASM code can include it to find the address of `mins`, which the ISR needs to increment once per minute.
 *
 *  Created on: Jul 18, 2024
 *      Author: passp
 */

#ifndef PERSISTENT_H_
#define PERSISTENT_H_

#include "timeblock.h"

// Here is the persistent data that we store in "information memory" FRAM that survives power cycles
// and reprogramming.

struct __attribute__((__packed__)) persistent_data_t {

    rv3032_time_block_t programmed_time;        // Calendar time when this unit was Programmed. Used to initialize the RTC on first power up.
    rv3032_time_block_t launched_time;          // Time when this unit was launched relative to programmed time. Set when trigger pulled, never read.


    // State. We have 3 persistent states, (1) first startup fresh from factory programming, (2) ready to launch, (3) launched.
    // We make these volatile to ensure that the compiler actually writes changes to memory rather than trying to cache in a register

    volatile unsigned initalized_flag;                         // Set to 1 by program fixture after successfully power test. If !1, then we show "TEST".
    volatile unsigned commisisoned_flag;                       // Set to 1 after we commission, which involves inserting the batteries and trigger pin. This is when we set the RTC to the programmed time.
    volatile unsigned launched_flag;                           // Set to 1 when the trigger pin is pulled.

    volatile unsigned porsoltCount;                            // How many 0.1 seconds did the unit stay alive after power was removed during initialization?

    volatile unsigned tsl_powerup_count;                           // How many times have we booted up since we initialized (Max 65535. Should be 1 until first battery change in about 150 years.)

    // Time since launch
    volatile unsigned mins;             // It would be too much work to update this every second, so once a minute is good. Note that it is possible for this value to end up at `minutes_per_day`, in which case you must normalize it and increment days.
    volatile unsigned long days;        // Has to be long since 2^16 days is only ~180 years and we plan on working for much longer than that.

    // We need to be able to update the above values atomically so we use an interlock here so we can do the right thing in case we get interrupted exactly in the middle of an update.
    volatile unsigned update_flag;             // Set to 1 when an update is in progress (backup values are valid)
    volatile unsigned backup_mins;             // These backup values are captured before we set `update_flag`.
    volatile unsigned long backup_days;

};

// Tell compiler/linker to put this in "info memory" that we set up in the linker file to live at 0x1800
// This area of memory never gets overwritten, not by power cycle and not by downloading a new binary image into program FRAM.

extern persistent_data_t persistent_data;


#endif /* PERSISTENT_H_ */

#include <msp430.h>
#include <limits.h>
#include "util.h"
#include "pins.h"
#include "i2c_master.h"

#include "error_codes.h"
#include "lcd_display.h"

#include "ram_isrs.h"

#include "tsl_asm.h"

//#include "timeblock.h"
#include "persistent.h"

#define RV_3032_I2C_ADDR (0b01010001)           // Datasheet 6.6

/*
// DEBUG VERSIONS
#define DEBUG_PULSE_ON()     SBI( DEBUGA_POUT , DEBUGA_B )
#define DEBUG_PULSE_OFF()    CBI( DEBUGA_POUT , DEBUGA_B )
*/

// PRODUCTION VERSIONS
#define DEBUG_PULSE_ON()     {}
#define DEBUG_PULSE_OFF()    {}

// Which PCB?
#define C2_IS_10K       // For PCBs after 9/2024 which have C2 replaced with a 10K resistor.

// Put the LCD into blinking mode

void lcd_blinking_mode() {
    LCDBLKCTL = LCDBLKPRE__64 | LCDBLKMOD_2;       // Clock prescaler for blink rate, "10b = Blinking of all segments"
}


// Turn off power to RV3032 (also takes care of making the IO pin not float and disabling the interrupt)
void depower_rv3032() {

    // Make Vcc pin to RV3032 ground. NOte that the RTC will likely keep running for a while off the backup
    // capacitor, but this should put it into backup mode where CLKOUT is disabled.
    CBI( RV3032_VCC_POUT , RV3032_VCC_B);

    // Now the CLKOUT pin is floating, so we will pull it
    SBI( RV3032_CLKOUT_PREN , RV3032_CLKOUT_B );    // Enable pull resistor (does not matter which way, just keep pin from floating to save power)

    CBI( RV3032_CLKOUT_PIE , RV3032_CLKOUT_B );     // Disable interrupt.
    CBI( RV3032_CLKOUT_PIFG , RV3032_CLKOUT_B );    // Clear any pending interrupt.

}

// Goes into LPM3.5 to save power since we can never wake from here.
// In LPMx.0 draws 1.38uA with the "First STart" message.
// In LPMx.5 draws 1.13uA with the "First STart" message.

// Clearing GIE does not prevent wakeup from LPMx.5 so all interrupts must have been individually disabled.
#pragma FUNC_NEVER_RETURNS
void sleepforeverandever(){


    /*

    // Manually disconnect the x.5 regulator switch Note that this does not seem to save any power over leaving automatic on.
    // Maybe this can save some power to leave the switch open when we are actually running the ISP, as long as we only write to the LCD
    // once? If we write more than once then we need to close the switch because LCD can only run at 40KHz on the small regulator.


    PM5CTL0 = LPM5SM                     // "Manual mode. The LPM3.5 switch is specified by LPM5SW bit setting in software."
                                         // "0b = LPMx.5 switch disconnected". Now the RTC and LCD are only powered from the tiny LPM3.5 regulator, so you can only Access them slowly (we do not access them at all from now on).
              | LOCKLPM5;                // Lock I/O pin and other LPMx.5 relevant (for example, RTC) configurations upon
                                         // entry to or exit from LPMx.5. After the LOCKLPM5 bit is set, it can be cleared
                                         // only by software or by a power cycle.
                                         // This bit is reset by a power cycle.

    */

    /*
    // These enable the LPMx.5 mode

    // First start message in LPM3   Mode = 1.25uA
    // First start message in LPM3.5 Mode = 1.56uA, but takes 350us to wake up compared to 10us.

    PMMCTL0 = PMMPW                    // Open PMM Registers for write
                                          // We do not include SVSHE so supervisor is off.
              | PMMREGOFF_L                // Set PMMREGOFF. "Regulator is turned off when going to LPM3 or LPM4. System enters LPM3.5 or LPM4.5, respectively."
              ;
*/
    // Make sure no pending interrupts here or else they might wake us!
    // Note that there is no power difference between LPM3 and LPM4 here, probably because OSC is already off because we are using VLO for the LCD?
    __bis_SR_register(LPM4_bits);     // // Enter LPM4 and sleep forever and ever and ever (no interrupts enabled so we will never get woken up)

}

// Assumes all interrupts have been individually disabled.
#pragma FUNC_NEVER_RETURNS
void blinkforeverandever(){
    lcd_blinking_mode();
    sleepforeverandever();
}

// Assumes all interrupts have been individually disabled.
#pragma FUNC_NEVER_RETURNS
void error_mode( byte code ) {
    lcd_show_errorcode(code);
    blinkforeverandever();
}


void wiggleFlashQ1() {
    SBI( Q1_TOP_LED_POUT , Q1_TOP_LED_B );
    __delay_cycles(10000);
    CBI( Q1_TOP_LED_POUT , Q1_TOP_LED_B );
}

void wiggleFlashQ2() {
    SBI( Q2_BOT_LED_POUT , Q2_BOT_LED_B );
    __delay_cycles(10000);
    CBI( Q2_BOT_LED_POUT , Q2_BOT_LED_B );
}


// Flash the bulbs in succession
// Leaves transistors driven off and flash bulbs off

void flash() {
    wiggleFlashQ1();
    __delay_cycles(30000);
    wiggleFlashQ2();
}

// Just gets all IO pins into an idle state
// Powers up the LCD bias voltage generator
// Powers up the RTC and configures MCU pin RV3032_CLKOUT as interrupt, but does not enable the interrupt.
// Does not enable interrupts on any pins


void initGPIO() {

    // TODO: use the full word-wide registers
    // Initialize all GPIO pins for low power OUTPUT + LOW
    P1DIR = 0xFF;P2DIR = 0xFF;P3DIR = 0xFF;P4DIR = 0xFF;
    P5DIR = 0xFF;P6DIR = 0xFF;P7DIR = 0xFF;P8DIR = 0xFF;
    // Configure all GPIO to Output Low
    P1OUT = 0x00;P2OUT = 0x00;P3OUT = 0x00;P4OUT = 0x00;
    P5OUT = 0x00;P6OUT = 0x00;P7OUT = 0x00;P8OUT = 0x00;

    // --- Flash bulbs off

    // Set Q1 & Q2 transistor pins to output (will be driven low by default so LEDs off)
    SBI( Q1_TOP_LED_PDIR , Q1_TOP_LED_B );
    SBI( Q2_BOT_LED_PDIR , Q2_BOT_LED_B );


    // --- TSP7A LCD voltage regulator
    SBI( TSP_IN_POUT , TSP_IN_B );          // Power up TSP
    SBI( TSP_IN_PDIR , TSP_IN_B );

    SBI( TSP_ENABLE_POUT , TSP_ENABLE_B );  // Enable TSP
    SBI( TSP_ENABLE_PDIR , TSP_ENABLE_B );

    // --- Debug pins

    // Debug pins
    SBI( DEBUGA_PDIR , DEBUGA_B );          // DEBUGA=Output. Currently used to time how long the ISR takes

    CBI( DEBUGB_PDIR , DEBUGB_B );          // DEBUGB=Input
    SBI( DEBUGB_POUT , DEBUGB_B );          // Pull up
    SBI( DEBUGB_PREN , DEBUGB_B );          // Currently checked at power up, if low then we go into testonly mode.

    // --- RV3032

    // ~INT in from RV3032 as INPUT with PULLUP
    // We don't use this for now, so set to drive low.

    SBI( RV3032_INT_PDIR , RV3032_INT_B ); // INPUT

    // Note that we can leave the RV3032 EVI pin as is - tied LOW on the PCB so it does not float (we do not use it)
    // It is hard tied low so that it does not float during battery changes when the MCU will not be running

    // Power to RV3032

    CBI( RV3032_GND_POUT , RV3032_GND_B);
    SBI( RV3032_GND_PDIR , RV3032_GND_B);

    SBI( RV3032_VCC_PDIR , RV3032_VCC_B);
    SBI( RV3032_VCC_POUT , RV3032_VCC_B);

    // Now we need to setup interrupt on RTC CLKOUT pin to wake us on each rising edge (1Hz)
    // Note that we do not *enable* it yet.

    CBI( RV3032_CLKOUT_PDIR , RV3032_CLKOUT_B );    // Set input
    CBI( RV3032_CLKOUT_PIES , RV3032_CLKOUT_B );    // Interrupt on rising edge (Driven by RV3032 CLKOUT pin which we program to run at 1Hz).

    /* RV3230 App Guide Section 4.21.1:
     *  the 1 Hz clock can be enabled
     *  on CLKOUT pin. The positive edge corresponds to the 1 Hz tick for the clock counter increment (except for
     *  the possible positive edge when the STOP bit is cleared).
     */

/*****************************************************************************
*
* A software bitbanged i2c taken from here..
*
*    https://github.com/bigjosh/TSL/blob/master/software/AS7/TSL/USI_TWI_Master.c
*
* ...which was based on the original AVR AVR310 TWI hardware master code.
*
* It has been modified first to be software bitbang, and then second to use MSP rather than AVR hardware IO.
*
* Usage             : Initialize the USI module by calling the USI_TWI_Master_Initialise()
*                     function. Hence messages/data are transceived on the bus using
*                     the USI_TWI_Transceive() function. The transceive function
*                     returns a status byte, which can be used to evaluate the
*                     success of the transmission.
*
****************************************************************************/


#include <msp430.h>
#include "util.h"
#include "pins.h"
#include "i2c_master.h"

#define BIT_TIME_US     (5)          // How long should should we wait between bit transitions?

#define _delay_us(x) (__delay_cycles(x))    // For now we are running 1Mhz




// TODO: Drive SCL high rather than pull?
// TODO: Drive SDA rather than pull when we are transmitting? Maybe risky?


// Is there a better way to abstract out MSP430 pins than a text macro?

// These are open collector signals, so never drive high - only drive low or pull high

// The init functions put the pins into " Totem-pole with Pull-up" mode
// In this mode the pin is:
//  pulled high when DIR =0
//  driven low when DIR =1

// Assumes OUT bits are still at startup default of 0

static inline void scl_init(void) {
    I2C_CLK_PDIR |= _BV(I2C_CLK_B);
}


static inline void sda_pull_init(void) {
    I2C_DTA_PREN |= _BV(I2C_DTA_B);
}

static inline void sda_drive_low(void) {
    I2C_DTA_POUT &= ~_BV( I2C_DTA_B );
    I2C_DTA_PDIR |= _BV( I2C_DTA_B );
}


static inline void sda_pull_high(void) {
    I2C_DTA_PDIR &= ~_BV( I2C_DTA_B );
    I2C_DTA_POUT |= _BV( I2C_DTA_B );
}

static inline void scl_drive_low(void) {
    I2C_CLK_POUT &= ~_BV( I2C_CLK_B );
}

static inline void scl_drive_high(void) {
    I2C_CLK_POUT |= _BV( I2C_CLK_B );
}

static inline uint8_t sda_read(void) {
    return I2C_DTA_PIN & _BV( I2C_DTA_B );
}





/*---------------------------------------------------------------
 USI TWI single master initialization function
---------------------------------------------------------------*/
void i2c_init( void )
{


    /*

        // TEST PINS
        I2C_DTA_PDIR |= _BV( I2C_DTA_B );

        I2C_DTA_POUT |= _BV( I2C_DTA_B );
        _delay_us(BIT_TIME_US);
        I2C_DTA_POUT &= ~_BV( I2C_DTA_B );
        _delay_us(BIT_TIME_US);

        I2C_CLK_PDIR |= _BV( I2C_CLK_B );

        I2C_CLK_POUT |= _BV( I2C_CLK_B );
        _delay_us(BIT_TIME_US);
        I2C_CLK_POUT &= ~_BV( I2C_CLK_B );
        _delay_us(BIT_TIME_US);
    */

  sda_pull_init();
  sda_pull_high();

  scl_init();
  scl_drive_high();

  /*
  while (1) {
    scl_drive_low();
    _delay_us(BIT_TIME_US);
    scl_pull_high();
    _delay_us(BIT_TIME_US);
  }
  */


  // This leaves us with both SCL and SDA high, which is an idle state
}


// Drive both pins low

void i2c_shutdown() {

    // SCL low first so we don't do an inadvertent START
    scl_drive_low();
    _delay_us(BIT_TIME_US);
    sda_drive_low();
    _delay_us(BIT_TIME_US);

}


// Write a byte out to the slave and look for ACK bit
// Assumes SCL low, SDA doesn't matter

// Returns 0=success, SDA high (ACK bit released), SCL low.

static unsigned char USI_TWI_Write_Byte( unsigned char data ) {

    for( uint8_t bitMask=0b10000000; bitMask !=0; bitMask>>=1 ) {

        // setup data bit

        if ( data & bitMask) {
            sda_pull_high();
        } else {
            sda_drive_low();

        }

        // clock it out

        _delay_us(BIT_TIME_US);

        scl_drive_high();           // Clock in the next address bit

        _delay_us(BIT_TIME_US);

        scl_drive_low();

    }

    // The device acknowledges the address by driving SDIO
    // low after the next falling SCLK edge, for 1 cycle.

    sda_pull_high();            // Pull SDA high so we can see if the slave is driving low
    _delay_us(BIT_TIME_US);     // Not needed, but so we can see what is happening on the scope
    scl_drive_high();
    _delay_us(BIT_TIME_US);     // TODO: Don't need all these delays

    uint8_t ret = sda_read();   // slave should be driving low now
    scl_drive_low();            // Slave release
    _delay_us(BIT_TIME_US);

    // TODO: CHeck ret

    return(ret);

}

// readFlag=1 leaves in read mode
// readFlag=0 leaves in write mode
// Returns 0 on success, 1 if no ACK bit received.
// Assumes SCL high
// Returns with SCL low, SDA wahtever last bit (r/w bit) was

static unsigned char i2c_start( unsigned char slave , unsigned char readFlag) {

    // We assume that we enter in idle state since that is how all public functions leave us

    _delay_us(BIT_TIME_US);         // Make sure we have been in idle at least long enough to see the falling SDA

    // Data transfer is always initiated by a Bus Master device. A high to low transition on the SDA line, while
    // SCL is high, is defined to be a START condition or a repeated start condition.

    sda_drive_low();

    _delay_us(BIT_TIME_US);

    scl_drive_low();

    // A START condition is always followed by the (unique) 7-bit slave address (MSB first) and then w/r bit

    // The control word is latched internally on
    // rising SCLK edges and is eight bits in length, comprised
    // of a seven bit device address equal to 0010000b and a
    // read/write bit (write = 0 and read = 1).

    uint8_t controlword = (slave << 1) | readFlag;

    return USI_TWI_Write_Byte( controlword );

}

// Assumes on entry SCL low
// Returns with bus idle, SCL high SDA high


static void i2c_stop(void) {

    // Data transfer ends with the STOP condition
    // (rising edge of SDIO while SCLK is high).

    // Q: Is this Really needed? Can we just do repeat starts and save this code? Spec is vague if address is reset on start.
    // A: Yes, we need this because it is possible that the FM_IC is holding the SDA line low
    // wait for us to clock out the MSB of the next byte!

    sda_drive_low();
    _delay_us(BIT_TIME_US);     // Give is a moment to stabilize in case
    scl_drive_high();
    _delay_us(BIT_TIME_US);

    sda_pull_high();            // SDA low to high while SCLK is high is a STOP
    _delay_us(BIT_TIME_US);

}

// Write the bytes pointed to by buffer
// addr is the chip bus address
// assumes bus is idle on entry, Exists with bus idle
// Returns 0 on success

unsigned char USI_TWI_Write_Data_No_stop(unsigned char slave, unsigned char addr , const uint8_t *buffer , uint8_t count)
{

    i2c_start( slave , 0 );      // TODO: check for error

    USI_TWI_Write_Byte( addr );      // select starting register to write to


    // Note here we can't really break out readByte() becuase the last byte
    // is special since we do not ACK it but instead send a STOP.

    while (count--) {

        USI_TWI_Write_Byte( *buffer );

        buffer++;

    }

    // No stop here.

    return(0);

}

// Write the bytes pointed to by buffer
// addr is the chip bus address
// assumes bus is idle on entry, Exists with bus idle
// Returns 0 on success

unsigned char i2c_write(unsigned char slave, unsigned char addr , const void *in_buffer , uint8_t count)
{
    unsigned char *buffer = (unsigned char *)in_buffer;

    i2c_start( slave , 0 );      // TODO: check for error

    USI_TWI_Write_Byte( addr );      // select starting register to write to


    // Note here we can't really break out readByte() becuase the last byte
    // is special since we do not ACK it but instead send a STOP.

    while (count--) {

        USI_TWI_Write_Byte( *buffer );

        buffer++;

    }


    // End transaction with bus in idle

    i2c_stop();

    return(0);

}


// Fill data buffer with bytes read from TWI
// addr is the chip bus address
// assumes bus is idle on entry, Exists with bus idle
// Returns 0 on success

unsigned char i2c_read(unsigned char slave, unsigned char addr  , void *in_buffer , uint8_t count)
{

    unsigned char *buffer = (unsigned char *)in_buffer;

    i2c_start( slave , 0 );      // "CPU transmits the RX8900's slave address with the R/W bit set to write mode."

    USI_TWI_Write_Byte( addr );     // "CPU transfers address for reading from RX8900."

    // Write returns with SDA high (ACK bit released), SCL low.

    // We are doing a restart here, so force clock high, then Start() will pull sda low with clock high

    scl_drive_high();
    _delay_us(BIT_TIME_US);
    _delay_us(BIT_TIME_US);
    _delay_us(BIT_TIME_US);

    i2c_start( slave , 1 );      // "CPU transfers RESTART condition [Sr] (in which case, CPU does not transfer a STOP condition [P])"

    // SCL low

    while (count) {

        unsigned char data=0;

        for( uint8_t bitMask=0b10000000; bitMask !=0; bitMask>>=1 ) {

            // Clock in the data bits

            scl_drive_high();           // Clock in the first data bit

            _delay_us(BIT_TIME_US);

            if (sda_read()) {

                data |= bitMask;

            }

            scl_drive_low();

            _delay_us(BIT_TIME_US);

        }

        // SCLK low here
        // SDA should be pulled high and not driven low by the FMIC because
        // we are reading so it is our turn to ACK now

        *buffer = data;

        buffer++;

        count--;

        if (count) {

            //After each byte of data is read,
            //the controller IC must drive an acknowledge (SDIO = 0)
            //if an additional byte of data will be requested. Data
            //transfer ends with the STOP condition.

            sda_drive_low();            // drive SDA to ACK that we read the byte
            _delay_us(BIT_TIME_US);     // Not needed, but so we can see what is happening on the scope


            scl_drive_high();            // Clock out the ACK bit
            _delay_us(BIT_TIME_US);

            scl_drive_low();
            _delay_us(BIT_TIME_US);     // Not necessary
            sda_pull_high();            // Back to normal condition pulling SDA high (slave will have next data bit on bus now)
            _delay_us(BIT_TIME_US);

            // Ready for next bit..

        }
    }

    // Ok, we got all the bits we need.
    // We did not send a ACK on the last byte, so
    // SCL is still low from the final data bit.
    // SDA is pulled high because the slave is waiting for use to drive low to ACK (we will STOP instead)

    /*
        FROM TI:

        "Once the master has received the number of bytes it is expecting, it
        will send a NACK, signaling to the slave to halt communications and release the bus. The master will
        follow this up with a STOP condition."

        https://www.google.com/url?sa=t&rct=j&q=&esrc=s&source=web&cd=1&cad=rja&uact=8&ved=0ahUKEwj9mr_HuobYAhVJON8KHfV0CeMQFggoMAA&url=http%3A%2F%2Fwww.ti.com%2Flit%2Fan%2Fslva704%2Fslva704.pdf&usg=AOvVaw0MO8lWY9iHs3PZqsN6fgWm

        From FM_IC Daata sheet:

        "After each byte of data is read,
        the controller IC must drive an acknowledge (SDIO = 0)
        if an additional byte of data will be requested. Data
        transfer ends with the STOP condition. After every
        STOP condition, the internal address counter is reset."

        This actually makes sense if you consider the case where the high bit in the
        next data byte being read is a 0. In this case, the FM_IC will hold the SDA line LOW
        after the ACK bit is clocked, making it impossible to send the stop condition.

        This actually happened in the wild when issuing a WRITE to do a seek after issuing a
        RED to get he the currently tuned station for a save.

    */

    scl_drive_high();            // SDA is is high, so we are clocking out a NAK
    _delay_us(BIT_TIME_US);
    scl_drive_low();            // finish clocking out a NAK

    i2c_stop();

    // End transaction with bus in idle

    return(0);

}

     */

    // Note that we do not enable the CLKOUT interrupt until we enter RTL or TSL mode

    // --- Trigger

    // By default we set the trigger to drive low so it will not use power regardless if the pin is in or out.
    // When the trigger is out, the pin is shorted to ground.
    // We will switch it to pull-up later if we need to (because we have not launched yet).

    CBI( TRIGGER_POUT , TRIGGER_B );      // low
    SBI( TRIGGER_PDIR , TRIGGER_B );      // drive

    // Note that we do not enable the trigger pin interrupt here. It will get enabled when we
    // switch to ready-to-lanch mode when the trigger is inserted at the factory. The interrupt will then get
    // disabled again and the pull up will get disabled after the trigger is pulled since once that happens we
    // dont care about the trigger state anymore and we don't want to waste power with either the pull-up getting shorted to ground
    // if they leave the trigger out, or from unnecessary ISR calls if they put the trigger in and pull it out again (or if it breaks and bounces).

    // Disable IO on the LCD power pins
    SYSCFG2 |= LCDPCTL;

    // Disable the GPIO power-on default high-impedance mode
    // to activate the above configured port settings
    PM5CTL0 &= ~LOCKLPM5;

}

